import os, sys
P = sys.argv[1]
SKILLS = "contrib/claude/skills/contrib-issue contrib/claude/skills/contrib-validate contrib/claude/skills/contrib-pr quality/claude/skills/quality-report release/claude/skills/release-prepare release/claude/skills/release-evidence release/claude/skills/release-verify docs-audit/claude/skills/docs-audit".split()
def front(path):
    text = open(path, encoding="utf-8").read()
    assert text.startswith("---\n"), path
    head, body = text[4:].split("\n---\n", 1)
    return head.splitlines(), body

bad = []
for s in SKILLS:
    f = os.path.join(P, s, "SKILL.md")
    if not os.path.isfile(f):
        bad.append("missing:" + s); continue
    head, _ = front(f)
    keys = dict(l.split(":", 1) for l in head if ":" in l and not l.startswith(" "))
    if keys.get("name", "").strip() != os.path.basename(s): bad.append("name:" + s)
    if keys.get("disable-model-invocation", "").strip() != "true": bad.append("invocable:" + s)
    if not keys.get("argument-hint", "").strip(): bad.append("hint:" + s)
print("skills=%d bad=%s" % (len(SKILLS), ",".join(bad) or "none"))
PY
