import os, re, sys, yaml
P = sys.argv[1]
PH = re.compile(r"<[A-Za-z][A-Za-z0-9_. -]*>")
# A command starts with an assignment, a group, or a program a repository runs; prose does not.
FIRST = re.compile(r"([A-Za-z_][A-Za-z0-9_]*=|[{(]|\./|(cd|bash|sh|python3|dotnet|docfx|npm|npx|node|docker|git|gh|test|make|pwsh|cargo|go|mvn|gradle)\s)")
RUN = ("build", "test", "test_integration", "coverage", "sonar", "release_readiness")
bad, packs = [], 0
for pack in ("repo-orkeon", "repo-orkeon-workshop"):
    d = yaml.safe_load(open(os.path.join(P, pack, "references", "repo.yaml"), encoding="utf-8"))
    packs += 1
    rel, com = d.get("release") or {}, d.get("commands") or {}
    chan = rel.get("channels")
    if chan is not None:
        if not isinstance(chan, list) or not chan: bad.append(pack + ":channels-not-a-list")
        else:
            bad += ["%s:channel-%d" % (pack, i) for i, c in enumerate(chan)
                    if not (isinstance(c, dict) and str(c.get("name") or "").strip() and str(c.get("check") or "").strip())]
        if not (rel.get("workflows") or {}).get("release"): bad.append(pack + ":no-workflows.release")
    for key in ("windows_jobs",):
        if key in rel and not isinstance(rel[key], list): bad.append(pack + ":" + key + "-not-a-list")
    docs = com.get("docs_checks")
    if docs is not None and not isinstance(docs, list): bad.append(pack + ":docs_checks-not-a-list")
    runs = [("commands." + k, com[k]) for k in RUN if k in com]
    runs += [("commands.docs_checks[%d]" % i, c) for i, c in enumerate(docs or [])]
    for key, value in runs:
        if not isinstance(value, str) or not value.strip(): bad.append(pack + ":" + key + "-not-a-command")
        elif PH.search(value): bad.append(pack + ":" + key + "-placeholder:" + PH.search(value).group(0))
        elif not FIRST.match(value.strip()): bad.append(pack + ":" + key + "-not-a-command:" + value.split()[0])
# /release-prepare reports a key a repository pack leaves out as not applicable.
prep = open(os.path.join(P, "release/claude/skills/release-prepare/SKILL.md"), encoding="utf-8").read()
if "not applicable (no <key>)" not in prep: bad.append("release-prepare:no-not-applicable")
print("packs=%d bad=%s" % (packs, ",".join(bad) or "none"))
PY
